insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('anxiety', 'Тревога и стресс', 'Постоянное напряжение и невозможность расслабиться', 'Кажется, я уже не помню, что значит жить спокойно.', 'Постоянная тревога — не черта характера и не проявление слабости. Это реакция психики, причины которой можно понять и с которой можно работать. Главная задача — не бороться с собой, а понять, что поддерживает это состояние.', array['Трудно расслабиться, даже когда объективно всё в порядке', 'Постоянно прокручиваете в голове варианты развития событий', 'Часто ожидаете худшего и стараетесь всё контролировать', 'Сложно отключиться от мыслей перед сном', 'Быстро устаёте, даже если физически почти ничего не делали']::text[], array['Снизить уровень постоянного внутреннего напряжения', 'Легче справляться со стрессовыми ситуациями', 'Улучшить качество сна', 'Перестать жить в ожидании худшего', 'Вернуть ощущение контроля над своей жизнью']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('relationships', 'Отношения', 'Партнёрство, близость, конфликты и расставания', 'Мы вроде вместе, но как будто говорим на разных языках.', 'Сложности в отношениях редко возникают из-за одного человека. Чаще это сочетание накопившихся обид, разных ожиданий и способов выражать чувства. С этим можно работать — вдвоём или индивидуально.', array['Разговоры всё чаще заканчиваются ссорами или молчанием', 'Есть ощущение, что вас не слышат и не понимают', 'Близость сменилась привычкой или отдалением', 'Трудно пережить расставание или измену', 'Страшно строить новые отношения после прошлого опыта']::text[], array['Научиться говорить так, чтобы вас слышали', 'Понимать свои и чужие потребности в отношениях', 'Выходить из конфликтов без разрушения близости', 'Пережить расставание и восстановить опору', 'Строить отношения, в которых комфортно']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('selfesteem', 'Самооценка и уверенность', 'Самокритика, сомнения и ощущение «я недостаточно хорош»', 'Что бы я ни делал, кажется, что этого всегда мало.', 'Неуверенность — не приговор и не «характер». Это выученный способ относиться к себе, который сформировался в определённых условиях. Его можно постепенно менять, опираясь на реальные факты о себе.', array['Постоянно сравниваете себя с другими не в свою пользу', 'Трудно принимать похвалу и признавать свои успехи', 'Боитесь ошибиться и часто откладываете важные шаги', 'Сложно говорить «нет» и отстаивать свои границы', 'Внутренний критик звучит громче любой поддержки']::text[], array['Снизить градус внутренней критики', 'Опираться на свои ценности, а не на чужие оценки', 'Спокойнее принимать решения и ошибаться', 'Выстраивать личные границы без чувства вины', 'Почувствовать устойчивость и право быть собой']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('burnout', 'Подавленность и выгорание', 'Эмоциональное истощение, апатия и потеря мотивации', 'Я как будто выключен. Всё делаю на автопилоте.', 'Подавленное состояние и выгорание — это не лень и не слабость. Так психика сообщает, что ресурсы на исходе. Работа строится бережно: сначала восстановление опоры, затем — причины истощения.', array['Утро начинается с усталости, а не с сил', 'То, что раньше радовало, больше не приносит удовольствия', 'Трудно заставить себя делать даже простые вещи', 'Появилась раздражительность или полное безразличие', 'Ощущение, что «закончились силы» и ничего не хочется']::text[], array['Постепенно вернуть энергию и интерес к жизни', 'Понять, что именно истощает, и перестроить нагрузку', 'Восстановить сон и режим восстановления', 'Научиться замечать ранние признаки перегрузки', 'Вернуть ощущение смысла в работе и отношениях']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('family', 'Семья и дети', 'Детско-родительские отношения, подростки, семейные кризисы', 'Мы любим друг друга, но почему-то всё время ссоримся.', 'В семье сложности возникают не потому, что кто-то «плохой». Меняются роли, накапливается усталость, у каждого свой способ переживать трудности. Работа помогает услышать друг друга без поиска виноватых.', array['Ребёнок отдалился, и вы не знаете, как вернуть контакт', 'Подростковый возраст превратил дом в поле конфликтов', 'После рождения ребёнка отношения с партнёром изменились', 'Семья проходит через развод или большие перемены', 'Повторяются одни и те же ссоры без решения']::text[], array['Восстановить контакт с ребёнком или подростком', 'Выходить из семейных конфликтов бережнее', 'Договариваться о ролях и обязанностях без обид', 'Пройти кризис или развод с меньшими потерями', 'Вернуть в дом ощущение тепла и безопасности']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('addictions', 'Зависимости', 'Алкоголь, игры, соцсети, еда, созависимость', 'Я говорю себе «это в последний раз» — и всё повторяется.', 'Зависимость — это не слабоволие, а способ психики справляться с напряжением, который вышел из-под контроля. Мы работаем без осуждения: с причинами, а не только с последствиями. Отдельное направление — помощь родственникам.', array['Всё труднее контролировать привычку, которая мешает жить', 'Близкие всё чаще говорят, что беспокоятся за вас', 'Настроение зависит от возможности «сорваться»', 'Вы строите жизнь вокруг зависимости близкого человека', 'Попытки «взять себя в руки» дают короткий результат']::text[], array['Понять, какую роль зависимость играет в вашей жизни', 'Восстановить контроль без войны с собой', 'Найти другие способы справляться с напряжением', 'Выстроить здоровые границы с зависимым близким', 'Снизить риск срывов и укрепить устойчивость']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('crisis', 'Кризисные ситуации', 'Травматические события, утраты, тяжёлые перемены', 'Все говорят «время лечит», но мне не становится легче.', 'После тяжёлых событий невозможно «просто забыть» — психике нужна поддержка, чтобы переработать опыт. Работа идёт бережно, в вашем темпе, без давления и требований «отпустить и жить дальше».', array['Навязчивые воспоминания или сны о произошедшем', 'Оцепенение и ощущение, что жизнь разделилась на «до» и «после»', 'Переживание утраты близкого человека', 'Трудная адаптация после экстремального опыта', 'Тревога и страхи, которых раньше не было']::text[], array['Вернуть ощущение безопасности в повседневной жизни', 'Снизить интенсивность тяжёлых воспоминаний', 'Прожить утрату, не разрушаясь', 'Восстановить сон и способность отдыхать', 'Постепенно вернуть себе будущее и планы']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('growth', 'Личные изменения', 'Баланс, решения, адаптация к переменам, цели', 'Со мной всё в порядке. Но я чувствую, что могу жить лучше.', 'Психолог нужен не только в кризис. Большая аудитория людей приходит за развитием: разобраться в себе, принять решение, адаптироваться к переменам. Это работа на ясность и осознанный выбор.', array['Стоите перед важным решением и не можете выбрать', 'Жизнь изменилась — переезд, новая роль, новый этап', 'Хочется большего баланса между работой и жизнью', 'Цели есть, но что-то мешает к ним двигаться', 'Хочется лучше понимать себя и свои желания']::text[], array['Принять важное решение с опорой на свои ценности', 'Легче адаптироваться к переменам', 'Выстроить баланс между сферами жизни', 'Развить навыки общения и уверенного поведения', 'Двигаться к целям системно, а не рывками']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into directions (id, title, short, quote, about, symptoms, outcomes) values ('career', 'Бизнес и карьера', 'Руководители, предприниматели, профессиональные кризисы', 'Внешне всё успешно. Внутри — постоянное напряжение.', 'ASHER понимает специфику высокой нагрузки. Это практическая работа с состоянием, решениями и коммуникацией — конфиденциально и без общих слов. Отдельный формат — сопровождение руководителей и предпринимателей.', array['Высокая ответственность и невозможность расслабиться', 'Подготовка к собеседованиям и карьерным изменениям', 'Рабочие конфликты и сложные коммуникации', 'Профессиональное выгорание на фоне успеха', 'Одиночество руководителя: не с кем обсудить решения']::text[], array['Управлять нагрузкой без потери эффективности', 'Увереннее проходить карьерные переходы', 'Разрешать рабочие конфликты экологично', 'Вернуть интерес к делу и ощущение смысла', 'Принимать сильные решения из спокойного состояния']::text[]) on conflict (id) do update set title = excluded.title, short = excluded.short, quote = excluded.quote, about = excluded.about, symptoms = excluded.symptoms, outcomes = excluded.outcomes;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000001', 'Лейла Мамедова', 'Клинический психолог, КПТ-терапевт', 12, 13000, array['online', 'inperson']::session_format[], array['anxiety', 'burnout', 'selfesteem']::text[], array['Русский', 'Азербайджанский']::text[], 4.9, 127, 'Работаю с тревожными состояниями и выгоранием в когнитивно-поведенческом подходе. Помогаю вернуть ощущение контроля через понятные, проверенные техники.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000002', 'Дмитрий Волков', 'Семейный психолог', 15, 16000, array['online', 'inperson']::session_format[], array['family', 'relationships']::text[], array['Русский']::text[], 4.8, 98, 'Пятнадцать лет работаю с парами и семьями. Верю, что почти любой конфликт — это непрожитый разговор, которому нужно помочь состояться.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000003', 'Айсель Гусейнова', 'Психолог-консультант', 8, 9000, array['online']::session_format[], array['selfesteem', 'growth', 'relationships']::text[], array['Русский', 'Азербайджанский', 'Английский']::text[], 4.9, 84, 'Сопровождаю людей в периоды перемен: новые роли, решения, поиск себя. Бережно и структурно, с опорой на ваши ценности.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000004', 'Рустам Алиев', 'Психолог, специалист по зависимостям', 17, 14000, array['online', 'inperson']::session_format[], array['addictions', 'family']::text[], array['Русский', 'Азербайджанский']::text[], 4.7, 65, 'Работаю с химическими и поведенческими зависимостями, а также с родственниками. Без осуждения, с причинами, а не только последствиями.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000005', 'Анна Керимова', 'Кризисный психолог, травматерапевт', 11, 15000, array['online', 'inperson']::session_format[], array['crisis', 'anxiety']::text[], array['Русский', 'Английский']::text[], 5, 73, 'Помогаю проживать утраты и последствия тяжёлых событий. Работаю в подходах EMDR и соматической терапии — бережно и в вашем темпе.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000006', 'Эльвин Багиров', 'Бизнес-психолог, executive-коуч', 14, 22000, array['online']::session_format[], array['career', 'burnout', 'growth']::text[], array['Русский', 'Азербайджанский', 'Английский']::text[], 4.8, 56, 'Сопровождаю руководителей и предпринимателей: нагрузка, решения, выгорание на фоне успеха. Конфиденциально и по делу.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000007', 'Нигяр Сафарова', 'Детский и подростковый психолог', 9, 10000, array['online', 'inperson']::session_format[], array['family', 'selfesteem']::text[], array['Русский', 'Азербайджанский']::text[], 4.9, 91, 'Работаю с подростками и родителями. Помогаю вернуть контакт в семье, когда кажется, что вы говорите на разных языках.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into specialists (id, display_name, role_title, experience_years, price, formats, direction_ids, languages, rating, reviews_count, about) values ('11111111-0000-4000-8000-000000000008', 'Марат Исмаилов', 'Психотерапевт, гештальт-подход', 10, 11000, array['online']::session_format[], array['relationships', 'burnout', 'growth']::text[], array['Русский']::text[], 4.7, 62, 'Помогаю замечать, как вы строите отношения с людьми и с собой, и находить в них больше свободы и живости.') on conflict (id) do update set display_name = excluded.display_name, role_title = excluded.role_title, experience_years = excluded.experience_years, price = excluded.price, formats = excluded.formats, direction_ids = excluded.direction_ids, languages = excluded.languages, rating = excluded.rating, reviews_count = excluded.reviews_count, about = excluded.about;
insert into programs (id, title, subtitle, duration_days) values ('prog-anxiety-30', '30 дней снижения тревожности', 'Каждый день — короткая теория и одно упражнение на 10–15 минут', 30) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, duration_days = excluded.duration_days;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 1, 'Знакомство с тревогой', 'Тревога — древняя система защиты, а не поломка. Она ошибается в сторону ложной тревоги, потому что так безопаснее для выживания.', 'Запишите три ситуации за сегодня, когда тревога включалась. Что было триггером?') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 2, 'Тело первым знает', 'Тревога живёт в теле: дыхание, плечи, челюсть, живот. Мысли догоняют позже.', 'Три раза за день просканируйте тело на 30 секунд. Где напряжение?') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 3, 'Дыхание 4-7-8', 'Длинный выдох активирует парасимпатическую систему — физиологический тормоз тревоги.', 'Вдох на 4 счёта, пауза 7, выдох 8. Три подхода утром и вечером.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 4, 'Мысли — не факты', 'Тревожная мысль ощущается как правда, но это лишь прогноз, и обычно — худший из возможных.', 'Поймайте одну тревожную мысль и запишите её. Просто запишите.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 5, 'Проверка прогнозов', 'Мозг редко сверяет тревожные прогнозы с реальностью. Начнём это делать за него.', 'К вчерашней мысли допишите: что случилось на самом деле?') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 6, 'Окно тревоги', 'Тревога растёт, достигает пика и спадает сама — если её не подкармливать избеганием.', 'Заметив тревогу, побудьте с ней 90 секунд, не отвлекаясь. Оцените до/после.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 7, 'Итоги недели', 'Семь дней наблюдения — вы уже видите тревогу со стороны. Это главный сдвиг.', 'Перечитайте записи недели. Отметьте один повторяющийся паттерн.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 8, 'Избегание кормит тревогу', 'Каждое избегание приносит облегчение сейчас и усиливает тревогу завтра. Это главный механизм её поддержания.', 'Составьте список из трёх вещей, которые вы избегаете из-за тревоги.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 9, 'Лестница смелости', 'С избеганием работают постепенно: от простого к сложному, шаг за шагом.', 'Расставьте свои три пункта от лёгкого к трудному. Выберите самый лёгкий.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 10, 'Первый шаг', 'Действие вопреки тревоге — единственное, что реально перенастраивает систему угроз.', 'Сделайте самый лёгкий пункт из лестницы. Запишите, что почувствовали.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 11, 'Заземление 5-4-3-2-1', 'Внимание — рычаг: когда оно в ощущениях «здесь и сейчас», тревоге не хватает топлива.', 'Практика 5-4-3-2-1 дважды в течение дня, не дожидаясь тревоги.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 12, 'Кофеин, сон, экраны', 'Тревожная система чувствительна к физиологии: недосып и стимуляторы снижают порог срабатывания.', 'Сегодня: кофе только до полудня, экран за час до сна — выключен.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 13, 'Время для беспокойства', 'Парадоксальная техника: тревоге выделяют официальные 15 минут в день — и она перестаёт размазываться по всем часам.', 'Назначьте «час беспокойства». Все тревожные мысли дня — на бумагу, разбор только в это время.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 14, 'Экватор наблюдения', 'Две недели практики меняют не тревогу, а ваши отношения с ней. Это и есть цель.', 'Сравните средний балл настроения первой и второй недели в дневнике.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 15, 'Катастрофизация', '«А что если...» — любимый жанр тревоги. Разворачиваем сценарий до конца: что тогда? И что я сделаю?', 'Возьмите один «а что если» и допишите его до конца: как именно вы справитесь.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 16, 'Вероятность vs возможность', 'Тревога путает «возможно» и «вероятно». Возможно почти всё, вероятно — немногое.', 'Оцените вероятность своего худшего сценария в процентах. Честно.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 17, 'Круг контроля', 'Тревога тянет контролировать неконтролируемое. Энергия возвращается, когда усилия идут туда, где есть влияние.', 'Разделите текущие беспокойства на два списка: влияю / не влияю.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 18, 'Действие в круге', 'Один конкретный шаг в зоне влияния снижает тревогу лучше часа размышлений.', 'Выберите пункт из списка «влияю» и сделайте по нему одно действие.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 19, 'Тревога и опора на тело', 'Регулярная умеренная нагрузка — доказанный способ снизить фоновую тревожность.', '20 минут быстрой ходьбы. Заметьте состояние до и после.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 20, 'Письмо тревоге', 'Когда тревоге дают голос на бумаге, она перестаёт шептать из-за спины.', 'Напишите тревоге короткое письмо: что вы поняли о ней за 20 дней.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 21, 'Три недели', 'Навык замечать → называть → выбирать реакцию уже формируется. Осталось закрепление.', 'Отметьте три ситуации, где вы отреагировали иначе, чем месяц назад.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 22, 'Ценности вместо страхов', 'Устойчивость строится не на отсутствии страха, а на ясности, ради чего вы действуете.', 'Запишите три ценности, ради которых стоит выдерживать дискомфорт.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 23, 'Шаг по лестнице', 'Возвращаемся к лестнице смелости: следующий уровень.', 'Сделайте второй пункт из вашей лестницы избеганий.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 24, 'Самосострадание', 'Жёсткость к себе усиливает тревогу. Поддержка — снижает. Это физиология, а не сентиментальность.', 'Заметив самокритику, ответьте себе так, как ответили бы другу.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 25, 'Тревога о тревоге', 'Страх самой тревоги — последний рубеж. Она неприятна, но не опасна, и вы уже это проверили.', 'Перечитайте день 6. Напишите: что тревога может вам сделать на самом деле?') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 26, 'Ресурсные ритуалы', 'Предсказуемые восстанавливающие ритуалы дают психике сигнал безопасности.', 'Выберите один вечерний ритуал на 15 минут и проведите его сегодня.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 27, 'Люди как опора', 'Разделённая тревога слабеет. Изоляция — усиливает.', 'Расскажите одному близкому человеку об одном своём страхе.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 28, 'План на срыв', 'Откаты — часть пути. Важно не отсутствие срывов, а скорость возвращения.', 'Составьте план из трёх шагов на случай сильной тревожной волны.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 29, 'Что я забираю с собой', 'Инструменты работают, только пока ими пользуются. Выберите свои.', 'Выпишите три техники программы, которые сработали лучше всего.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into program_days (program_id, day, title, theory, exercise) values ('prog-anxiety-30', 30, 'Новая точка отсчёта', 'Тревога останется частью жизни — но теперь у неё есть рамки, а у вас есть выбор.', 'Напишите короткое письмо себе через полгода: что хотите сохранить.') on conflict (program_id, day) do update set title = excluded.title, theory = excluded.theory, exercise = excluded.exercise;
insert into programs (id, title, subtitle, duration_days) values ('prog-sleep-14', '14 дней здорового сна', 'Перезагрузка режима: гигиена сна, вечерние ритуалы, работа с ночными мыслями', 14) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, duration_days = excluded.duration_days;
insert into programs (id, title, subtitle, duration_days) values ('prog-selfcare-21', '21 день заботы о себе', 'Практики самоподдержки против внутреннего критика', 21) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, duration_days = excluded.duration_days;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-sleep', 'Не могу уснуть', 'Почему мозг не выключается ночью', 'text', 6, 'anxiety', 'Перед сном психика впервые за день остаётся без задач — и достаёт всё отложенное. Разбираем технику «выгрузки мыслей» и правило 20 минут.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-sleep-audio', 'Не могу уснуть', 'Аудио-практика: тело тяжелеет', 'audio', 12, 'anxiety', 'Двенадцатиминутная практика прогрессивной мышечной релаксации для вечера. Голос ведёт от стоп к макушке.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-worry', 'Постоянно тревожусь', 'Тревога: сигнализация, которая заела', 'text', 8, 'anxiety', 'Тревога — исправная система защиты с неправильной настройкой чувствительности. Что её поддерживает и почему «просто успокойся» не работает.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-worry-practice', 'Постоянно тревожусь', 'Практика «5-4-3-2-1» за 3 минуты', 'practice', 3, 'anxiety', 'Пять предметов, которые видите. Четыре звука. Три ощущения. Быстрое заземление, когда тревога накрывает волной.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-teen', 'Конфликт с подростком', 'Подросток хлопает дверью: что за этим стоит', 'text', 9, 'family', 'Сепарация — не бунт против вас, а работа взросления. Как оставаться взрослым рядом с бурей и не терять контакт.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-teen-video', 'Конфликт с подростком', 'Видео: три фразы, которые закрывают диалог', 'video', 7, 'family', 'Разбор типичных родительских реплик, которые звучат как забота, а слышатся как контроль — и чем их заменить.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-burnout', 'Выгораю на работе', 'Выгорание ≠ усталость: как отличить', 'text', 7, 'burnout', 'Усталость проходит после отдыха. Выгорание — нет. Три стадии истощения и почему отпуск не лечит третью.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-burnout-practice', 'Выгораю на работе', 'Аудит энергии: неделя в четырёх колонках', 'practice', 15, 'burnout', 'Практика для поиска утечек: что наполняет, что опустошает, что делаете из страха, а что — из смысла.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-fight', 'Ссоримся с партнёром', 'Анатомия ссоры: 4 всадника Готтмана', 'text', 8, 'relationships', 'Критика, презрение, оборона, молчание — паттерны, которые предсказывают разрыв. Как заметить их у себя первым.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-fight-video', 'Ссоримся с партнёром', 'Видео: пауза 20 минут, которая спасает разговор', 'video', 6, 'relationships', 'Физиология затопления: почему в ссоре вы «не слышите» друг друга буквально, и как правильно брать тайм-аут.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-noself', 'Не верю в себя', 'Внутренний критик: голос, который врёт', 'text', 7, 'selfesteem', 'Откуда берётся ощущение «я недостаточно хорош» и почему критик всегда говорит одними и теми же словами.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-noself-practice', 'Не верю в себя', 'Дневник фактов: 10 минут против обесценивания', 'practice', 10, 'selfesteem', 'Простая вечерняя практика: три факта дня, которые критик хотел бы стереть. Через месяц — другой взгляд на себя.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-loss', 'Переживаю утрату', 'Горе не по этапам: как это бывает на самом деле', 'text', 10, 'crisis', 'Мифы о «пяти стадиях», волны горевания и почему «держаться» — худший совет. Что действительно помогает проживать.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-phone', 'Залипаю в телефоне', 'Дофаминовая петля: почему рука сама тянется', 'text', 6, 'addictions', 'Лента устроена как игровой автомат. Как работает переменное подкрепление и с чего начать возвращать себе время.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-decision', 'Не могу принять решение', 'Практика: решение через ценности, а не страхи', 'practice', 12, 'growth', 'Матрица из четырёх вопросов, которая отделяет «чего я боюсь» от «что мне важно». Для больших развилок.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
insert into library_items (id, situation, title, kind, minutes, direction_id, excerpt) values ('lib-boss', 'Устал руководить', 'Одиночество руководителя', 'text', 8, 'career', 'Чем выше позиция, тем меньше людей, с кем можно быть неуверенным. Почему это истощает и где брать опору.') on conflict (id) do update set situation = excluded.situation, title = excluded.title, kind = excluded.kind, minutes = excluded.minutes, direction_id = excluded.direction_id, excerpt = excluded.excerpt;
